1	package main
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"os"
9		"path/filepath"
10		"sort"
11		"strings"
12		"time"
13	)
14	
15	// 数据目录布局：
16	//
17	//	<dir>/state.json      全部业务数据（客户、用量、账单、封账状态）
18	//	<dir>/state.json.tmp  原子写入临时文件（保存后 rename 覆盖）
19	//
20	// 所有命令顺序运行，单次调用内完成“读入—修改—整体原子落盘”，
21	// 因此账单与封账状态在同一次保存中持久化，不会出现半写状态。
22	
23	const stateVersion = 1
24	
25	type customer struct {
26		ID    string `json:"id"`
27		Name  string `json:"name"`
28		Price int64  `json:"price_fen"` // 固定单价，非负整数分，创建后不可修改
29	}
30	
31	type usageRecord struct {
32		ID         string `json:"id"`
33		CustomerID string `json:"customer_id"`
34		Time       string `json:"time"` // RFC3339，保留原始输入用于去重判定
35		Quantity   int64  `json:"quantity"`
36	}
37	
38	type billLine struct {
39		UsageID  string `json:"usage_id"`
40		Time     string `json:"time"`
41		Quantity int64  `json:"quantity"`
42		LineFee  int64  `json:"line_fee_fen"`
43	}
44	
45	type bill struct {
46		ID         string     `json:"id"`
47		CustomerID string     `json:"customer_id"`
48		Month      string     `json:"month"` // YYYY-MM（UTC）
49		TotalQty   int64      `json:"total_quantity"`
50		UnitPrice  int64      `json:"unit_price_fen"`
51		TotalFee   int64      `json:"total_fee_fen"`
52		Lines      []billLine `json:"lines"`
53		CreatedAt  string     `json:"created_at"`
54	}
55	
56	// adjustment 是对已结算账单的一次费用调整（正数补收、负数减免）。
57	// 记录一旦写入永不删除；撤销只是追加撤销信息，保留原记录。
58	type adjustment struct {
59		ID           string `json:"id"`
60		CustomerID   string `json:"customer_id"`
61		Month        string `json:"month"` // YYYY-MM（UTC），与所属账单一致
62		Amount       int64  `json:"amount_fen"`
63		Reason       string `json:"reason"`
64		Seq          int64  `json:"seq"` // 全局递增操作序号，决定历史展示顺序
65		CreatedAt    string `json:"created_at"`
66		Revoked      bool   `json:"revoked"`
67		RevokeReason string `json:"revoke_reason,omitempty"`
68		RevokeSeq    int64  `json:"revoke_seq,omitempty"`
69		RevokedAt    string `json:"revoked_at,omitempty"`
70	}
71	
72	// paymentAllocation 是一笔收款在某个已结算月份上的分配（正整数分）。
73	type paymentAllocation struct {
74		Month  string `json:"month"`      // YYYY-MM（UTC），须已有账单
75		Amount int64  `json:"amount_fen"` // 正整数分
76	}
77	
78	// payment 是一笔实收登记：同一客户的一笔汇款（总额 Total 分）按分配列表
79	// 计入一个或多个已结算月份；单账单收款视为只有一项分配的汇款。
80	// 记录一旦写入永不删除；撤销只是追加撤销信息，整笔撤销全部分配并保留
81	// 原记录，撤销后该笔不再计入实收，也不会因重放而恢复。
82	type payment struct {
83		ID           string              `json:"id"`
84		CustomerID   string              `json:"customer_id"`
85		Total        int64               `json:"total_fen"` // 收款总额，正整数分，等于分配合计
86		Note         string              `json:"note"`
87		Allocations  []paymentAllocation `json:"allocations"` // 至少一项，月份不重复，按月份升序保存
88		Seq          int64               `json:"seq"`         // 全局递增操作序号，决定历史展示顺序
89		CreatedAt    string              `json:"created_at"`
90		Revoked      bool                `json:"revoked"`
91		RevokeReason string              `json:"revoke_reason,omitempty"`
92		RevokeSeq    int64               `json:"revoke_seq,omitempty"`
93		RevokedAt    string              `json:"revoked_at,omitempty"`
94	}
95	
96	// UnmarshalJSON 兼容旧版单账单收款格式（month + amount_fen，无 allocations）：
97	// 读入时归一化为一项分配，之后一律按新格式写回。
98	func (p *payment) UnmarshalJSON(data []byte) error {
99		type plain payment // 去掉方法，避免递归
100		var raw struct {
101			plain
102			Month  string `json:"month"`      // 旧格式：所属账单月份
103			Amount int64  `json:"amount_fen"` // 旧格式：收款金额
104		}
105		if err := json.Unmarshal(data, &raw); err != nil {
106			return err
107		}
108		*p = payment(raw.plain)
109		if len(p.Allocations) == 0 && raw.Month != "" {
110			p.Allocations = []paymentAllocation{{Month: raw.Month, Amount: raw.Amount}}
111			p.Total = raw.Amount
112		}
113		return nil
114	}
115	
116	// amountFor 返回该收款在指定月份的分配金额；无分配时为 0。
117	func (p *payment) amountFor(month string) int64 {
118		for _, al := range p.Allocations {
119			if al.Month == month {
120				return al.Amount
121			}
122		}
123		return 0
124	}
125	
126	// correction 是对一笔未撤销收款的分配更正：客户、总额、备注、原账单及
127	// 应付不变，仅把该笔收款当前生效的分配整体替换为完整新分配。记录一旦写入
128	// 永不删除；首次登记内容永久保留，bill pay / bill remit 仍按原始分配判重，
129	// 更正不影响收款身份。可连续更正，每次以当时最新分配为起点。
130	type correction struct {
131		ID          string              `json:"id"`
132		PaymentID   string              `json:"payment_id"` // 目标收款标识
133		Reason      string              `json:"reason"`
134		Allocations []paymentAllocation `json:"allocations"` // 完整新分配，至少一项，月份不重复，按月份升序保存
135		Seq         int64               `json:"seq"`         // 全局递增操作序号，与调整/收款及其撤销共用
136		CreatedAt   string              `json:"created_at"`
137	}
138	
139	type state struct {
140		Version     int                     `json:"version"`
141		Customers   map[string]*customer    `json:"customers"`
142		Usage       map[string]*usageRecord `json:"usage"`       // 全局唯一用量标识 -> 记录
143		Bills       map[string]*bill        `json:"bills"`       // 客户 + "|" + 月份 -> 账单
144		Adjustments map[string]*adjustment  `json:"adjustments"` // 全局唯一调整标识 -> 记录
145		Payments    map[string]*payment     `json:"payments"`    // 全局唯一收款标识 -> 记录（与调整标识相互独立，可同名）
146		Corrections map[string]*correction  `json:"corrections"` // 全局唯一更正标识 -> 记录（与收款、调整标识相互独立，可同名）
147		NextSeq     int64                   `json:"next_seq"`    // 已分配的最大操作序号（调整/收款/更正及其撤销共用）
148		path        string                  `json:"-"`
149	}
150	
151	// loadStore 读取数据目录；目录不存在时按需创建并视为空库。
152	// 已存在但损坏或不可读取的数据一律报错，绝不当作空库覆盖。
153	func loadStore(dir string) (*state, error) {
154		p := filepath.Join(dir, "state.json")
155		data, err := os.ReadFile(p)
156		if err != nil {
157			if errors.Is(err, os.ErrNotExist) {
158				if mkErr := os.MkdirAll(dir, 0o755); mkErr != nil {
159					return nil, fmt.Errorf("无法创建数据目录 %s: %w", dir, mkErr)
160				}
161				return newState(p), nil
162			}
163			return nil, fmt.Errorf("数据文件不可读取 %s: %w", p, err)
164		}
165	
166		var s state
167		dec := json.NewDecoder(bytes.NewReader(data))
168		if err := dec.Decode(&s); err != nil {
169			return nil, fmt.Errorf("数据文件已损坏（不是有效的 JSON）%s: %w", p, err)
170		}
171		// 拒绝尾部多余内容，避免静默吞掉异常数据。
172		if dec.More() {
173			return nil, fmt.Errorf("数据文件已损坏（JSON 之后存在多余内容）: %s", p)
174		}
175		if err := s.validate(); err != nil {
176			return nil, fmt.Errorf("数据文件已损坏: %w", err)
177		}
178		// 旧版本数据文件没有 adjustments/payments/corrections/next_seq 字段：
179		// 视为零调整、零实收、零更正。
180		if s.Adjustments == nil {
181			s.Adjustments = map[string]*adjustment{}
182		}
183		if s.Payments == nil {
184			s.Payments = map[string]*payment{}
185		}
186		if s.Corrections == nil {
187			s.Corrections = map[string]*correction{}
188		}
189		s.path = p
190		return &s, nil
191	}
192	
193	func newState(p string) *state {
194		return &state{
195			Version:     stateVersion,
196			Customers:   map[string]*customer{},
197			Usage:       map[string]*usageRecord{},
198			Bills:       map[string]*bill{},
199			Adjustments: map[string]*adjustment{},
200			Payments:    map[string]*payment{},
201			Corrections: map[string]*correction{},
202			path:        p,
203		}
204	}
205	
206	// validate 对读入的库做一致性检查，任何异常都按损坏处理。
207	func (s *state) validate() error {
208		if s.Version != stateVersion {
209			return fmt.Errorf("不支持的数据版本 %d（仅支持 %d）", s.Version, stateVersion)
210		}
211		if s.Customers == nil || s.Usage == nil || s.Bills == nil {
212			return errors.New("缺少必要的数据节")
213		}
214		for id, c := range s.Customers {
215			if c == nil {
216				return fmt.Errorf("客户 %q 的数据为空", id)
217			}
218			if c.ID != id {
219				return fmt.Errorf("客户标识不一致: 键 %q / 记录 %q", id, c.ID)
220			}
221			if c.ID == "" || c.Name == "" {
222				return fmt.Errorf("客户 %q 的标识或名称为空", id)
223			}
224			if c.Price < 0 {
225				return fmt.Errorf("客户 %q 单价为负", id)
226			}
227		}
228		for id, u := range s.Usage {
229			if u == nil {
230				return fmt.Errorf("用量 %q 的数据为空", id)
231			}
232			if u.ID != id {
233				return fmt.Errorf("用量标识不一致: 键 %q / 记录 %q", id, u.ID)
234			}
235			if u.ID == "" {
236				return errors.New("存在空的用量标识")
237			}
238			if _, ok := s.Customers[u.CustomerID]; !ok {
239				return fmt.Errorf("用量 %q 引用了不存在的客户 %q", u.ID, u.CustomerID)
240			}
241			if u.Quantity <= 0 {
242				return fmt.Errorf("用量 %q 的数量非正", u.ID)
243			}
244			if _, err := time.Parse(time.RFC3339, u.Time); err != nil {
245				return fmt.Errorf("用量 %q 的时间不是 RFC3339: %w", u.ID, err)
246			}
247		}
248		for key, b := range s.Bills {
249			if b == nil {
250				return fmt.Errorf("账单 %q 的数据为空", key)
251			}
252			if billKey(b.CustomerID, b.Month) != key {
253				return fmt.Errorf("账单键不一致: 键 %q / 客户月份 %s|%s", key, b.CustomerID, b.Month)
254			}
255			if _, ok := s.Customers[b.CustomerID]; !ok {
256				return fmt.Errorf("账单 %q 引用了不存在的客户 %q", key, b.CustomerID)
257			}
258			if !validMonth(b.Month) {
259				return fmt.Errorf("账单 %q 的月份无效", key)
260			}
261			if len(b.Lines) == 0 {
262				return fmt.Errorf("账单 %q 没有明细", key)
263			}
264			var qty, fee int64
265			for _, ln := range b.Lines {
266				u, ok := s.Usage[ln.UsageID]
267				if !ok {
268					return fmt.Errorf("账单 %q 引用了不存在的用量 %q", key, ln.UsageID)
269				}
270				if u.CustomerID != b.CustomerID || u.Time != ln.Time || u.Quantity != ln.Quantity {
271					return fmt.Errorf("账单 %q 的明细 %q 与用量记录不一致", key, ln.UsageID)
272				}
273				if !inMonth(u.Time, b.Month) {
274					return fmt.Errorf("账单 %q 的明细 %q 不在账期内", key, ln.UsageID)
275				}
276				var err error
277				qty, err = add64(qty, ln.Quantity)
278				if err != nil {
279					return fmt.Errorf("账单 %q 汇总数量溢出", key)
280				}
281				fee, err = add64(fee, ln.LineFee)
282				if err != nil {
283					return fmt.Errorf("账单 %q 汇总金额溢出", key)
284				}
285			}
286			if qty != b.TotalQty {
287				return fmt.Errorf("账单 %q 总数量与明细不符", key)
288			}
289			if fee != b.TotalFee {
290				return fmt.Errorf("账单 %q 总金额与明细不符", key)
291			}
292			c := s.Customers[b.CustomerID]
293			for _, ln := range b.Lines {
294				lf, err := mul64(ln.Quantity, c.Price)
295				if err != nil {
296					return fmt.Errorf("账单 %q 明细 %q 小计溢出", key, ln.UsageID)
297				}
298				if lf != ln.LineFee {
299					return fmt.Errorf("账单 %q 明细 %q 小计与数量×单价不符", key, ln.UsageID)
300				}
301			}
302			if b.UnitPrice != c.Price {
303				return fmt.Errorf("账单 %q 单价与客户固定单价不符", key)
304			}
305			// 封账期内不得存在游离于账单之外的用量（封账后新增被禁止，
306			// 而已入账记录理应全部在明细中）。
307			for _, u := range s.Usage {
308				if u.CustomerID == b.CustomerID && inMonth(u.Time, b.Month) {
309					found := false
310					for _, ln := range b.Lines {
311						if ln.UsageID == u.ID {
312							found = true
313							break
314						}
315					}
316					if !found {
317						return fmt.Errorf("客户 %s 的 %s 已封账，但用量 %q 未计入账单", b.CustomerID, b.Month, u.ID)
318					}
319				}
320			}
321		}
322	
323		// 调整与收款记录：标识、内容、引用与序号都必须自洽。
324		// 调整与收款共用同一个全局操作序号池；两者标识命名空间相互独立，
325		// 允许同名，各自判重与撤销。
326		if s.NextSeq < 0 {
327			return fmt.Errorf("操作序号计数器为负: %d", s.NextSeq)
328		}
329		seenSeq := make(map[int64]string) // 全局操作序号（登记与撤销共用同一池）-> 来源描述
330		for id, a := range s.Adjustments {
331			if a == nil {
332				return fmt.Errorf("调整 %q 的数据为空", id)
333			}
334			if a.ID != id {
335				return fmt.Errorf("调整标识不一致: 键 %q / 记录 %q", id, a.ID)
336			}
337			if a.ID == "" {
338				return errors.New("存在空的调整标识")
339			}
340			if a.Amount == 0 {
341				return fmt.Errorf("调整 %q 的金额为零", id)
342			}
343			if strings.TrimSpace(a.Reason) == "" {
344				return fmt.Errorf("调整 %q 的原因为空", id)
345			}
346			if !validMonth(a.Month) {
347				return fmt.Errorf("调整 %q 的月份无效", id)
348			}
349			if _, ok := s.Customers[a.CustomerID]; !ok {
350				return fmt.Errorf("调整 %q 引用了不存在的客户 %q", id, a.CustomerID)
351			}
352			if _, ok := s.Bills[billKey(a.CustomerID, a.Month)]; !ok {
353				return fmt.Errorf("调整 %q 引用了不存在的账单（客户 %s 月份 %s）", id, a.CustomerID, a.Month)
354			}
355			if a.Seq < 1 || a.Seq > s.NextSeq {
356				return fmt.Errorf("调整 %q 的操作序号越界", id)
357			}
358			if prev, dup := seenSeq[a.Seq]; dup {
359				return fmt.Errorf("调整 %q 与 %q 的操作序号重复", id, prev)
360			}
361			seenSeq[a.Seq] = "调整 " + id
362			if a.Revoked {
363				if strings.TrimSpace(a.RevokeReason) == "" {
364					return fmt.Errorf("调整 %q 已撤销但撤销原因为空", id)
365				}
366				if a.RevokeSeq <= a.Seq || a.RevokeSeq > s.NextSeq {
367					return fmt.Errorf("调整 %q 的撤销序号越界", id)
368				}
369				if prev, dup := seenSeq[a.RevokeSeq]; dup {
370					return fmt.Errorf("撤销调整 %q 与 %q 的操作序号重复", id, prev)
371				}
372				seenSeq[a.RevokeSeq] = "撤销调整 " + id
373			} else if a.RevokeReason != "" || a.RevokeSeq != 0 {
374				return fmt.Errorf("调整 %q 未撤销但存在撤销信息", id)
375			}
376		}
377		for id, p := range s.Payments {
378			if p == nil {
379				return fmt.Errorf("收款 %q 的数据为空", id)
380			}
381			if p.ID != id {
382				return fmt.Errorf("收款标识不一致: 键 %q / 记录 %q", id, p.ID)
383			}
384			if p.ID == "" {
385				return errors.New("存在空的收款标识")
386			}
387			if p.Total <= 0 {
388				return fmt.Errorf("收款 %q 的总额不是正整数", id)
389			}
390			if strings.TrimSpace(p.Note) == "" {
391				return fmt.Errorf("收款 %q 的备注为空", id)
392			}
393			if _, ok := s.Customers[p.CustomerID]; !ok {
394				return fmt.Errorf("收款 %q 引用了不存在的客户 %q", id, p.CustomerID)
395			}
396			if len(p.Allocations) == 0 {
397				return fmt.Errorf("收款 %q 没有分配", id)
398			}
399			seenMonths := make(map[string]bool)
400			var sum int64
401			for _, al := range p.Allocations {
402				if !validMonth(al.Month) {
403					return fmt.Errorf("收款 %q 的分配月份 %q 无效", id, al.Month)
404				}
405				if seenMonths[al.Month] {
406					return fmt.Errorf("收款 %q 的分配月份 %s 重复", id, al.Month)
407				}
408				seenMonths[al.Month] = true
409				if al.Amount <= 0 {
410					return fmt.Errorf("收款 %q 在 %s 的分配金额不是正整数", id, al.Month)
411				}
412				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
413					return fmt.Errorf("收款 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
414				}
415				var err error
416				sum, err = add64(sum, al.Amount)
417				if err != nil {
418					return fmt.Errorf("收款 %q 的分配金额汇总溢出: %w", id, err)
419				}
420			}
421			if sum != p.Total {
422				return fmt.Errorf("收款 %q 的分配合计 %d 分与总额 %d 分不一致", id, sum, p.Total)
423			}
424			if p.Seq < 1 || p.Seq > s.NextSeq {
425				return fmt.Errorf("收款 %q 的操作序号越界", id)
426			}
427			if prev, dup := seenSeq[p.Seq]; dup {
428				return fmt.Errorf("收款 %q 与 %q 的操作序号重复", id, prev)
429			}
430			seenSeq[p.Seq] = "收款 " + id
431			if p.Revoked {
432				if strings.TrimSpace(p.RevokeReason) == "" {
433					return fmt.Errorf("收款 %q 已撤销但撤销原因为空", id)
434				}
435				if p.RevokeSeq <= p.Seq || p.RevokeSeq > s.NextSeq {
436					return fmt.Errorf("收款 %q 的撤销序号越界", id)
437				}
438				if prev, dup := seenSeq[p.RevokeSeq]; dup {
439					return fmt.Errorf("撤销收款 %q 与 %q 的操作序号重复", id, prev)
440				}
441				seenSeq[p.RevokeSeq] = "撤销收款 " + id
442			} else if p.RevokeReason != "" || p.RevokeSeq != 0 {
443				return fmt.Errorf("收款 %q 未撤销但存在撤销信息", id)
444			}
445		}
446		// 分配更正记录：标识、目标收款、原因、新分配与序号都必须自洽。
447		// 更正标识与收款、调整标识命名空间相互独立，允许同名。
448		for id, c := range s.Corrections {
449			if c == nil {
450				return fmt.Errorf("更正 %q 的数据为空", id)
451			}
452			if c.ID != id {
453				return fmt.Errorf("更正标识不一致: 键 %q / 记录 %q", id, c.ID)
454			}
455			if c.ID == "" {
456				return errors.New("存在空的更正标识")
457			}
458			p, ok := s.Payments[c.PaymentID]
459			if !ok {
460				return fmt.Errorf("更正 %q 引用了不存在的收款 %q", id, c.PaymentID)
461			}
462			if strings.TrimSpace(c.Reason) == "" {
463				return fmt.Errorf("更正 %q 的原因为空", id)
464			}
465			if len(c.Allocations) == 0 {
466				return fmt.Errorf("更正 %q 没有新分配", id)
467			}
468			seenMonths := make(map[string]bool)
469			var sum int64
470			for _, al := range c.Allocations {
471				if !validMonth(al.Month) {
472					return fmt.Errorf("更正 %q 的分配月份 %q 无效", id, al.Month)
473				}
474				if seenMonths[al.Month] {
475					return fmt.Errorf("更正 %q 的分配月份 %s 重复", id, al.Month)
476				}
477				seenMonths[al.Month] = true
478				if al.Amount <= 0 {
479					return fmt.Errorf("更正 %q 在 %s 的分配金额不是正整数", id, al.Month)
480				}
481				if _, ok := s.Bills[billKey(p.CustomerID, al.Month)]; !ok {
482					return fmt.Errorf("更正 %q 的分配引用了不存在的账单（客户 %s 月份 %s）", id, p.CustomerID, al.Month)
483				}
484				var err error
485				sum, err = add64(sum, al.Amount)
486				if err != nil {
487					return fmt.Errorf("更正 %q 的分配金额汇总溢出: %w", id, err)
488				}
489			}
490			if sum != p.Total {
491				return fmt.Errorf("更正 %q 的分配合计 %d 分与关联收款 %q 的总额 %d 分不一致", id, sum, c.PaymentID, p.Total)
492			}
493			if c.Seq <= p.Seq || c.Seq > s.NextSeq {
494				return fmt.Errorf("更正 %q 的操作序号越界", id)
495			}
496			if p.Revoked && c.Seq > p.RevokeSeq {
497				return fmt.Errorf("更正 %q 的操作序号晚于关联收款 %q 的撤销序号", id, c.PaymentID)
498			}
499			if prev, dup := seenSeq[c.Seq]; dup {
500				return fmt.Errorf("更正 %q 与 %q 的操作序号重复", id, prev)
501			}
502			seenSeq[c.Seq] = "更正 " + id
503		}
504		// 每张账单：当前应付（原总金额 + 全部未撤销调整净额）必须介于
505		// 0 与有符号 64 位最大值之间；实收（全部未撤销收款按最新分配在该月
506		// 计入之和）必须满足 0 ≤ 实收 ≤ 当前应付。越界说明金额与记录不一致。
507		for key, b := range s.Bills {
508			_, payable, err := billTotals(b, adjustmentsFor(s, b.CustomerID, b.Month))
509			if err != nil {
510				return fmt.Errorf("账单 %q 的调整金额与记录不一致: %w", key, err)
511			}
512			received, err := paymentReceived(s, b.CustomerID, b.Month)
513			if err != nil {
514				return fmt.Errorf("账单 %q 的收款金额与记录不一致: %w", key, err)
515			}
516			if received > payable {
517				return fmt.Errorf("账单 %q 的实收 %d 分超过当前应付 %d 分", key, received, payable)
518			}
519		}
520		return nil
521	}
522	
523	// save 整体原子落盘：先写临时文件并同步，再 rename 覆盖。
524	// 只有完整保存成功后调用方才会向用户报告成功。
525	func (s *state) save() error {
526		if err := s.validate(); err != nil {
527			return fmt.Errorf("拒绝写入不一致的数据: %w", err)
528		}
529		data, err := json.MarshalIndent(s, "", "  ")
530		if err != nil {
531			return fmt.Errorf("序列化数据失败: %w", err)
532		}
533		data = append(data, '\n')
534	
535		tmp := s.path + ".tmp"
536		f, err := os.OpenFile(tmp, os.O_WRONLY|os.O_CREATE|os.O_TRUNC, 0o644)
537		if err != nil {
538			return fmt.Errorf("写入临时数据文件失败: %w", err)
539		}
540		if _, err := f.Write(data); err != nil {
541			f.Close()
542			os.Remove(tmp)
543			return fmt.Errorf("写入临时数据文件失败: %w", err)
544		}
545		if err := f.Sync(); err != nil {
546			f.Close()
547			os.Remove(tmp)
548			return fmt.Errorf("同步数据文件失败: %w", err)
549		}
550		if err := f.Close(); err != nil {
551			os.Remove(tmp)
552			return fmt.Errorf("关闭数据文件失败: %w", err)
553		}
554		if err := os.Rename(tmp, s.path); err != nil {
555			os.Remove(tmp)
556			return fmt.Errorf("替换数据文件失败: %w", err)
557		}
558		if dir, err := os.Open(filepath.Dir(s.path)); err == nil {
559			dir.Sync()
560			dir.Close()
561		}
562		return nil
563	}
564	
565	func billKey(customerID, month string) string {
566		return customerID + "|" + month
567	}
568	
569	// sealed 报告某客户的指定月份是否已封账。
570	func (s *state) sealed(customerID, month string) bool {
571		_, ok := s.Bills[billKey(customerID, month)]
572		return ok
573	}
574	
575	// adjustmentsFor 返回某客户某月账单的全部调整，按操作序号升序。
576	func adjustmentsFor(s *state, customerID, month string) []*adjustment {
577		var list []*adjustment
578		for _, a := range s.Adjustments {
579			if a.CustomerID == customerID && a.Month == month {
580				list = append(list, a)
581			}
582		}
583		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
584		return list
585	}
586	
587	// correctionsFor 返回某收款的全部分配更正，按操作序号升序。
588	func correctionsFor(s *state, paymentID string) []*correction {
589		var list []*correction
590		for _, c := range s.Corrections {
591			if c.PaymentID == paymentID {
592				list = append(list, c)
593			}
594		}
595		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
596		return list
597	}
598	
599	// currentAllocations 返回一笔收款当前生效的分配：无更正时为首次登记的
600	// 原始分配，否则为序号最大（最新）的更正的分配。
601	func currentAllocations(s *state, p *payment) []paymentAllocation {
602		var latest *correction
603		for _, c := range s.Corrections {
604			if c.PaymentID == p.ID && (latest == nil || c.Seq > latest.Seq) {
605				latest = c
606			}
607		}
608		if latest != nil {
609			return latest.Allocations
610		}
611		return p.Allocations
612	}
613	
614	// allocAmountFor 返回分配列表中指定月份的金额；无该月分配时为 0。
615	func allocAmountFor(allocs []paymentAllocation, month string) int64 {
616		for _, al := range allocs {
617			if al.Month == month {
618				return al.Amount
619			}
620		}
621		return 0
622	}
623	
624	// paymentsEverFor 返回历史上曾涉及某客户某月账单的全部收款（首次登记
625	// 分配或任一次更正的新分配涉及该月，即使后来被更正移出），按操作序号升序。
626	func paymentsEverFor(s *state, customerID, month string) []*payment {
627		var list []*payment
628		for _, p := range s.Payments {
629			if p.CustomerID != customerID {
630				continue
631			}
632			involved := p.amountFor(month) > 0
633			if !involved {
634				for _, c := range s.Corrections {
635					if c.PaymentID == p.ID && allocAmountFor(c.Allocations, month) > 0 {
636						involved = true
637						break
638					}
639				}
640			}
641			if involved {
642				list = append(list, p)
643			}
644		}
645		sort.Slice(list, func(i, j int) bool { return list[i].Seq < list[j].Seq })
646		return list
647	}
648	
649	// paymentReceived 返回全部未撤销收款按最新分配在指定月份计入的实收之和。
650	// 各笔分配均为正整数，用非负 64 位加法累加，溢出时返回错误。
651	func paymentReceived(s *state, customerID, month string) (int64, error) {
652		var received int64
653		for _, p := range s.Payments {
654			if p.CustomerID != customerID || p.Revoked {
655				continue
656			}
657			amt := allocAmountFor(currentAllocations(s, p), month)
658			if amt <= 0 {
659				continue
660			}
661			var err error
662			received, err = add64(received, amt)
663			if err != nil {
664				return 0, err
665			}
666		}
667		return received, nil
668	}
669	
670	// errPayableOutOfRange 表示当前应付越出 [0, 有符号 64 位最大值]。
671	var errPayableOutOfRange = errors.New("当前应付越界（须介于 0 与有符号 64 位最大值之间）")
672	
673	// billTotals 计算全部未撤销调整的净额与当前应付（原总金额 + 净额）。
674	// 净额按 128 位精确求和（与顺序无关），再校验应付落在
675	// [0, 有符号 64 位最大值] 内，全程整数运算。
676	func billTotals(b *bill, adjs []*adjustment) (net, payable int64, err error) {
677		var amounts []int64
678		for _, a := range adjs {
679			if !a.Revoked {
680				amounts = append(amounts, a.Amount)
681			}
682		}
683		net, err = sumSigned64(amounts...)
684		if err != nil {
685			return 0, 0, err
686		}
687		payable, err = addSigned64(b.TotalFee, net)
688		if err != nil {
689			return 0, 0, err
690		}
691		if payable < 0 {
692			return 0, 0, errPayableOutOfRange
693		}
694		return net, payable, nil
695	}
