1	package main
2	
3	import (
4		"errors"
5		"math"
6		"math/bits"
7		"strconv"
8	)
9	
10	// 金额、单价、数量均使用有符号 64 位整数（金额单位：人民币分），
11	// 全程整数运算，不经过浮点数。
12	
13	var errOverflow = errors.New("数量或金额运算超出有符号 64 位整数范围")
14	
15	// mul64 返回 a*b，溢出时返回错误。a、b 均非负。
16	func mul64(a, b int64) (int64, error) {
17		if a < 0 || b < 0 {
18			return 0, errOverflow
19		}
20		if a == 0 || b == 0 {
21			return 0, nil
22		}
23		if a > math.MaxInt64/b {
24			return 0, errOverflow
25		}
26		return a * b, nil
27	}
28	
29	// add64 返回 a+b，溢出时返回错误。a、b 均非负。
30	func add64(a, b int64) (int64, error) {
31		if a < 0 || b < 0 || a > math.MaxInt64-b {
32			return 0, errOverflow
33		}
34		return a + b, nil
35	}
36	
37	// addSigned64 返回 a+b（允许负数），溢出时返回错误。
38	func addSigned64(a, b int64) (int64, error) {
39		if (b > 0 && a > math.MaxInt64-b) || (b < 0 && a < math.MinInt64-b) {
40			return 0, errOverflow
41		}
42		return a + b, nil
43	}
44	
45	// neg64 返回 -a；a 为 math.MinInt64 时无法表示，返回错误。
46	func neg64(a int64) (int64, error) {
47		if a == math.MinInt64 {
48			return 0, errOverflow
49		}
50		return -a, nil
51	}
52	
53	// sumSigned64 精确求和一组有符号 64 位整数（内部按 128 位累加，
54	// 与求和顺序无关），最终结果超出有符号 64 位范围时返回错误。
55	func sumSigned64(vals ...int64) (int64, error) {
56		var hi, lo uint64
57		for _, v := range vals {
58			var carry uint64
59			lo, carry = bits.Add64(lo, uint64(v), 0)
60			// 符号扩展 v 的高位后连同进位一起累加。
61			sign := uint64(0)
62			if v < 0 {
63				sign = math.MaxUint64
64			}
65			hi, _ = bits.Add64(hi, sign, carry)
66		}
67		switch {
68		case hi == 0 && lo <= math.MaxInt64:
69			return int64(lo), nil
70		case hi == math.MaxUint64 && lo >= 1<<63:
71			return int64(lo), nil
72		default:
73			return 0, errOverflow
74		}
75	}
76	
77	// moneyFen 将“分”渲染为人民币金额，如 1234 -> "12.34 元"，5 -> "0.05 元"。
78	func moneyFen(fen int64) string {
79		neg := fen < 0
80		// 用无符号数取绝对值，避免 math.MinInt64 取负溢出。
81		u := uint64(fen)
82		if neg {
83			u = uint64(-(fen + 1)) + 1
84		}
85		s := strconv.FormatUint(u, 10)
