717	func cmdBillRevoke(dir, adjID, reason string) error {
718		if strings.TrimSpace(adjID) == "" {
719			return fmt.Errorf("调整标识不能为空")
720		}
721		if strings.TrimSpace(reason) == "" {
722			return fmt.Errorf("撤销原因不能为空")
723		}
724	
725		s, err := loadStore(dir)
726		if err != nil {
727			return err
728		}
729		a, ok := s.Adjustments[adjID]
730		if !ok {
731			return fmt.Errorf("调整标识 %q 不存在，无法撤销", adjID)
732		}
733	
734		if a.Revoked {
735			// 相同标识与相同原因重复撤销：幂等成功，不新增记录；
736			// 改用其他原因则拒绝。
737			if a.RevokeReason == reason {
738				fmt.Fprintf(stdout, "调整 %q 已撤销且撤销原因相同，幂等返回（不新增记录）：\n\n", adjID)
739				printAdjustment(a, s)
740				return nil
741			}
742			return fmt.Errorf("调整 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", adjID, a.RevokeReason)
743		}
744	
745		// 撤销只取消该笔调整的金额影响；若撤销后当前应付越界或低于实收则
746		// 拒绝，该调整仍保持有效，可先撤销误登记的收款或在其他合法调整
747		// 改变余额后重试。
748		b := s.Bills[billKey(a.CustomerID, a.Month)] // 载入时已校验存在
749		_, payable, err := billTotals(b, adjustmentsFor(s, a.CustomerID, a.Month))
750		if err != nil {
751			return fmt.Errorf("账单当前应付异常，拒绝撤销: %w", err)
752		}
753		received, err := paymentReceived(s, a.CustomerID, a.Month)
754		if err != nil {
755			return fmt.Errorf("实收累计异常，拒绝撤销: %w", err)
756		}
757		neg, err := neg64(a.Amount)
758		if err != nil {
759			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值，拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试")
760		}
761		newPayable, err := addSigned64(payable, neg)
762		if err != nil {
763			return fmt.Errorf("撤销后当前应付将超出有符号 64 位最大值（当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
764				payable, a.Amount)
765		}
766		if newPayable < 0 {
767			return fmt.Errorf("撤销后当前应付将为 %d 分（小于 0，当前 %d 分，取消 %+d 分），拒绝撤销；该调整仍有效，可在其他合法调整改变余额后重试",
768				newPayable, payable, a.Amount)
769		}
770		if newPayable < received {
771			return fmt.Errorf("撤销后当前应付 %d 分将低于实收 %d 分（当前 %d 分，取消 %+d 分），拒绝撤销；可先撤销误登记的收款再重试",
772				newPayable, received, payable, a.Amount)
773		}
774	
775		a.Revoked = true
776		a.RevokeReason = reason
777		a.RevokedAt = time.Now().UTC().Format(time.RFC3339)
778		s.NextSeq++
779		a.RevokeSeq = s.NextSeq
780	
781		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
782		if err := s.save(); err != nil {
783			a.Revoked = false
784			a.RevokeReason = ""
785			a.RevokedAt = ""
786			a.RevokeSeq = 0
787			s.NextSeq--
788			return err
789		}
790		fmt.Fprintf(stdout, "已撤销调整 %q（%s %+d 分），客户 %s 的 %s 当前应付 %d 分（%s）：\n\n",
791			adjID, adjustKind(a.Amount), a.Amount, a.CustomerID, a.Month, newPayable, moneyFen(newPayable))
792		printAdjustment(a, s)
793		return nil
794	}
