802		fmt.Fprintf(stdout, "月份：%s\n", a.Month)
803		fmt.Fprintf(stdout, "调整金额：%+d 分（%s，%s）\n", a.Amount, moneyFen(a.Amount), adjustKind(a.Amount))
804		fmt.Fprintf(stdout, "原因：%s\n", a.Reason)
