826	func cmdBillPay(dir, customerID, month, payID, amountText, note string) error {
827		if !validMonth(month) {
828			return fmt.Errorf("月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", month)
829		}
830		amount, err := parsePositiveAmount(amountText)
831		if err != nil {
832			return err
833		}
834		// 单账单收款视为只有一项分配的汇款，与 bill remit 共用同一核心。
