839	func cmdBillRemit(dir, customerID, payID, totalText, note string, allocArgs []string) error {
840		total, err := parsePositiveAmount(totalText)
841		if err != nil {
842			return err
843		}
844		allocs, err := parseAllocations(allocArgs)
845		if err != nil {
846			return err
847		}
848		// 分配合计必须等于总额，全程整数运算，溢出拒绝。
849		var sum int64
850		for _, al := range allocs {
851			sum, err = add64(sum, al.Amount)
852			if err != nil {
853				return fmt.Errorf("分配金额合计溢出有符号 64 位整数范围，拒绝登记")
854			}
855		}
856		if sum != total {
857			return fmt.Errorf("分配合计 %d 分与收款总额 %d 分不一致，拒绝登记", sum, total)
858		}
859		return registerPayment(dir, customerID, payID, total, note, allocs)
860	}
