862	// parseAllocations 解析 <YYYY-MM:金额分> 形式的分配列表：至少一项，
863	// 月份不得重复，每项金额为正整数分。
864	func parseAllocations(args []string) ([]paymentAllocation, error) {
865		if len(args) == 0 {
866			return nil, fmt.Errorf("分配列表不能为空，至少需要一项 <YYYY-MM:金额分>")
867		}
868		seen := make(map[string]bool)
869		allocs := make([]paymentAllocation, 0, len(args))
870		for _, arg := range args {
871			parts := strings.Split(arg, ":")
872			if len(parts) != 2 {
873				return nil, fmt.Errorf("分配项 %q 格式非法，应为 YYYY-MM:金额分（如 2026-09:500）", arg)
874			}
875			month := strings.TrimSpace(parts[0])
876			if !validMonth(month) {
877				return nil, fmt.Errorf("分配项 %q 的月份 %q 无效，必须是 YYYY-MM 形式（如 2026-09）", arg, parts[0])
878			}
879			if seen[month] {
880				return nil, fmt.Errorf("分配月份 %s 重复，拒绝登记", month)
881			}
882			seen[month] = true
883			amount, err := parsePositiveAmount(parts[1])
884			if err != nil {
885				return nil, fmt.Errorf("分配项 %q 的金额无效: %w", arg, err)
886			}
887			allocs = append(allocs, paymentAllocation{Month: month, Amount: amount})
888		}
889		return allocs, nil
890	}
