998	// formatAllocations 以 "2026-09:500,2026-10:300" 形式展示分配列表。
999	func formatAllocations(allocs []paymentAllocation) string {
1000		parts := make([]string, len(allocs))
1001		for i, al := range allocs {
1002			parts[i] = fmt.Sprintf("%s:%d", al.Month, al.Amount)
1003		}
1004		return strings.Join(parts, ",")
1005	}
