1018	func cmdBillUnpay(dir, payID, reason string) error {
1019		if strings.TrimSpace(payID) == "" {
1020			return fmt.Errorf("收款标识不能为空")
1021		}
1022		if strings.TrimSpace(reason) == "" {
1023			return fmt.Errorf("撤销原因不能为空")
1024		}
1025	
1026		s, err := loadStore(dir)
1027		if err != nil {
1028			return err
1029		}
1030		p, ok := s.Payments[payID]
1031		if !ok {
1032			return fmt.Errorf("收款标识 %q 不存在，无法撤销", payID)
1033		}
1034	
1035		if p.Revoked {
1036			// 相同标识与相同原因重复撤销：幂等成功，不新增历史；
1037			// 改用其他原因则拒绝。
1038			if p.RevokeReason == reason {
1039				fmt.Fprintf(stdout, "收款 %q 已撤销且撤销原因相同，幂等返回（不新增历史）：\n\n", payID)
1040				printPayment(p, s)
1041				return nil
1042			}
1043			return fmt.Errorf("收款 %q 已撤销（撤销原因 %q），改用其他原因重复撤销被拒绝", payID, p.RevokeReason)
1044		}
1045	
1046		// 撤销整笔生效：取消该笔在全部分配月份上的最新实收（经更正的以最新
1047		// 分配为准），不接受部分撤销；不改变应付、其他收款或调整，原收款、
1048		// 分配、更正与撤销原因永久保留。
1049		p.Revoked = true
1050		p.RevokeReason = reason
1051		p.RevokedAt = time.Now().UTC().Format(time.RFC3339)
1052		s.NextSeq++
1053		p.RevokeSeq = s.NextSeq
1054	
1055		// 撤销信息与原记录在同一次原子保存中持久化；保存失败则一切不生效。
1056		if err := s.save(); err != nil {
1057			p.Revoked = false
1058			p.RevokeReason = ""
1059			p.RevokedAt = ""
1060			p.RevokeSeq = 0
1061			s.NextSeq--
1062			return err
1063		}
1064		fmt.Fprintf(stdout, "已撤销收款 %q（总额 %d 分，%s），取消最新分配：\n", payID, p.Total, moneyFen(p.Total))
1065		printAllocationBalances(s, p, currentAllocations(s, p))
1066		fmt.Fprintln(stdout)
1067		printPayment(p, s)
1068		return nil
1069	}
1070	
1071	// printPayment 输出单笔收款记录：总额、首次登记的全部分配（永久保留，
1072	// 判重依据）与当前状态；经历过更正时同时展示当前生效的最新分配。
1073	// 各月应付/实收取自当前库状态。
1074	func printPayment(p *payment, s *state) {
1075		fmt.Fprintf(stdout, "收款标识：%s\n", p.ID)
1076		fmt.Fprintf(stdout, "客户：%s\n", p.CustomerID)
1077		fmt.Fprintf(stdout, "收款总额：%d 分（%s）\n", p.Total, moneyFen(p.Total))
1078		fmt.Fprintf(stdout, "备注：%s\n", p.Note)
1079		if p.Revoked {
1080			fmt.Fprintf(stdout, "当前状态：已撤销（撤销原因：%s）\n", p.RevokeReason)
1081		} else {
1082			fmt.Fprintf(stdout, "当前状态：实收中\n")
1083		}
1084		fmt.Fprintln(stdout, "分配明细（首次登记，永久保留）：")
1085		for i, al := range p.Allocations {
1086			b := s.Bills[billKey(p.CustomerID, al.Month)] // 载入时已校验存在
1087			_, payable, _ := billTotals(b, adjustmentsFor(s, p.CustomerID, al.Month))
1088			received, _ := paymentReceived(s, p.CustomerID, al.Month)
1089			fmt.Fprintf(stdout, "  %d. 月份 %s：分配 %d 分（%s）；当前应付 %d 分，实收合计 %d 分，未收余额 %d 分\n",
1090				i+1, al.Month, al.Amount, moneyFen(al.Amount), payable, received, payable-received)
1091		}
1092		if corrs := correctionsFor(s, p.ID); len(corrs) > 0 {
1093			fmt.Fprintf(stdout, "当前分配（经 %d 次更正，以最新为准）：%s\n",
1094				len(corrs), formatAllocations(currentAllocations(s, p)))
1095		}
1096	}
