func sortedByInstant(recs []*usageRecord) bool {
	for i := 1; i < len(recs); i++ {
		ti, _ := time.Parse(time.RFC3339, recs[i-1].Time)
		tj, _ := time.Parse(time.RFC3339, recs[i].Time)
		ui, uj := ti.UTC(), tj.UTC()
		if uj.Before(ui) || (uj.Equal(ui) && recs[i].ID <= recs[i-1].ID) {
			return false
		}
	}
	return true
}
